<?php
$tab=$_GET['tab']??'students';
$levelFilter=$_GET['level']??'all';$stageFilter=$_GET['stage']??'all';
$userSemesters=safeRun($pdo,"SELECT * FROM semesters ORDER BY start_date DESC,id DESC")->fetchAll();
$selectedUserSemesterId=(int)($_GET['semester_id']??$currentSemesterId);$selectedUserSemester=null;
foreach($userSemesters as $semesterRow)if((int)$semesterRow['id']===$selectedUserSemesterId)$selectedUserSemester=$semesterRow;
if(!$selectedUserSemester){$selectedUserSemesterId=(int)$currentSemesterId;foreach($userSemesters as $semesterRow)if((int)$semesterRow['id']===$selectedUserSemesterId)$selectedUserSemester=$semesterRow;}
$students=safeRun($pdo,"SELECT s.id,s.user_id,s.matric_number,s.level,s.programme,s.faculty,
 h.programme_type,h.project_title,h.status stage_status,h.attempt_number,h.enrolment_type,
 u.full_name,u.email,u.status,u.email_verified,u.phone,fr.final_score,fr.grade,fr.status result_status
 FROM student_stage_history h JOIN students s ON s.id=h.student_id JOIN users u ON u.id=s.user_id
 LEFT JOIN final_results fr ON fr.student_id=s.id AND fr.semester_id=h.semester_id
 WHERE h.semester_id=?
 ORDER BY FIELD(h.programme_type,'diploma_fyp1','diploma_fyp2','degree_fyp1','degree_fyp2'),u.full_name",[$selectedUserSemesterId])->fetchAll();
$lecturers=safeRun($pdo,"SELECT l.*,u.full_name,u.email,u.status,u.email_verified,u.phone,
 GROUP_CONCAT(CONCAT(lr.role_type,'|',lr.programme_type) ORDER BY FIELD(lr.role_type,'coordinator','supervisor','report_panel','presentation_panel'),lr.programme_type SEPARATOR ';;') role_pairs
 FROM lecturers l JOIN users u ON u.id=l.user_id LEFT JOIN lecturer_roles lr ON lr.lecturer_id=l.id AND lr.semester_id=?
 GROUP BY l.id,u.id ORDER BY u.full_name",[$selectedUserSemesterId])->fetchAll();
$filteredStudents=$students;
if($levelFilter!=='all')$filteredStudents=array_values(array_filter($filteredStudents,fn($s)=>$s['level']===$levelFilter));
if($stageFilter!=='all')$filteredStudents=array_values(array_filter($filteredStudents,fn($s)=>$s['programme_type']===$stageFilter));
$degreeCount=count(array_filter($students,fn($s)=>$s['level']==='degree'));$diplomaCount=count($students)-$degreeCount;
$addErr=$_GET['adderr']??'';$deleteMsg=$_GET['deleted']??'';
$tempPassword=$_SESSION['new_account_password']??null;$tempEmail=$_SESSION['new_account_email']??null;$mailSent=$_SESSION['new_account_mail_sent']??null;
unset($_SESSION['new_account_password'],$_SESSION['new_account_email'],$_SESSION['new_account_mail_sent']);
$programmeOptions=programmeOptions();
$semesterQuery='&semester_id='.$selectedUserSemesterId;
$canAddStudent=$selectedUserSemester&&((int)$selectedUserSemester['is_current']===1||empty($selectedUserSemester['activated_at']));
?>
<?php if($addErr): ?><div class="alert alert-danger small"><?= e(match($addErr){'email'=>'Use the correct institutional email domain.','identity'=>'The matric, email, level, FYP stage, or programme is invalid.','exists'=>'That email or matric number already exists.','phone'=>'A registered phone number is required.','mail'=>'Account created, but the temporary-password email could not be delivered. Configure SMTP and use the one-time password shown below.','error'=>'The account could not be created.',default=>'Please check the submitted information.'}) ?></div><?php endif; ?>
<?php if(($_GET['added']??'')==='1'): ?><div class="alert alert-success small"><strong>Account created successfully.</strong> <?php if($mailSent): ?>The temporary password was emailed to <?= e($tempEmail) ?>.<?php elseif($tempPassword): ?>Email delivery failed. One-time temporary password for <?= e($tempEmail) ?>: <code><?= e($tempPassword) ?></code><?php endif; ?></div><?php endif; ?>
<?php if($deleteMsg==='1'): ?><div class="alert alert-success small">User deleted successfully.</div><?php elseif($deleteMsg==='blocked'): ?><div class="alert alert-warning small">This user could not be deleted because protected academic records still depend on the account.</div><?php endif; ?>

<div class="card-fy mb-3"><form method="get" class="row g-2 align-items-end"><input type="hidden" name="view" value="users"><input type="hidden" name="tab" value="<?= e($tab) ?>"><div class="col-md-5"><label class="form-label small fw-semibold">Semester</label><select class="form-control-fy w-100" name="semester_id" onchange="this.form.submit()"><?php foreach($userSemesters as $semesterRow): ?><option value="<?= (int)$semesterRow['id'] ?>" <?= (int)$semesterRow['id']===$selectedUserSemesterId?'selected':'' ?>><?= e($semesterRow['name']) ?><?= $semesterRow['is_current']?' (Current)':(!$semesterRow['activated_at']?' (Upcoming)':' (Archived)') ?></option><?php endforeach; ?></select></div><div class="col-md-7"><div class="small text-muted">Student enrolments and lecturer roles shown below belong to the selected semester. All active lecturer accounts remain available, but a new semester begins with no assigned roles.</div></div></form></div>
<div class="d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2">
 <div class="d-flex gap-2"><a href="?view=users&tab=students<?= e($semesterQuery) ?>" class="filter-pill <?= $tab==='students'?'active':'' ?>">Students (<?= count($students) ?>)</a><a href="?view=users&tab=lecturers<?= e($semesterQuery) ?>" class="filter-pill <?= $tab==='lecturers'?'active':'' ?>">Lecturers (<?= count($lecturers) ?>)</a></div>
 <?php if($tab==='lecturers'||$canAddStudent): ?><button class="btn-fy-orange" data-bs-toggle="modal" data-bs-target="#<?= $tab==='lecturers'?'addLecturerModal':'addStudentModal' ?>"><i class="fa-solid fa-plus me-1"></i>Add <?= $tab==='lecturers'?'Lecturer':'Student' ?></button><?php endif; ?>
</div>
<?php if($tab==='students'): ?>
<div class="d-flex gap-2 mb-2 flex-wrap"><a href="?view=users&tab=students&level=all&stage=<?= e($stageFilter) ?><?= e($semesterQuery) ?>" class="filter-pill <?= $levelFilter==='all'?'active':'' ?>">All Levels (<?= count($students) ?>)</a><a href="?view=users&tab=students&level=degree&stage=<?= e($stageFilter) ?><?= e($semesterQuery) ?>" class="filter-pill <?= $levelFilter==='degree'?'active':'' ?>">Degree (<?= $degreeCount ?>)</a><a href="?view=users&tab=students&level=diploma&stage=<?= e($stageFilter) ?><?= e($semesterQuery) ?>" class="filter-pill <?= $levelFilter==='diploma'?'active':'' ?>">Diploma (<?= $diplomaCount ?>)</a></div>
<div class="d-flex gap-2 mb-3 flex-wrap"><a href="?view=users&tab=students&level=<?= e($levelFilter) ?>&stage=all<?= e($semesterQuery) ?>" class="filter-pill <?= $stageFilter==='all'?'active':'' ?>">All Stages</a><?php foreach(validProgrammeTypes() as $stage): ?><a href="?view=users&tab=students&level=<?= e($levelFilter) ?>&stage=<?= e($stage) ?><?= e($semesterQuery) ?>" class="filter-pill <?= $stageFilter===$stage?'active':'' ?>"><?= e(programmeTypeLabel($stage)) ?></a><?php endforeach; ?></div>
<?php endif; ?>
<div class="card-fy"><div class="table-responsive">
<?php if($tab==='students'): ?>
<table class="table-fy"><thead><tr><th>Matric</th><th>Student</th><th>Level / Stage</th><th>Programme</th><th>Status</th><th>Action</th></tr></thead><tbody>
<?php foreach($filteredStudents as $s): $progressionLabel=match(true){$s['stage_status']==='completed'=>'Completed FYP',$s['stage_status']==='promoted'||$s['enrolment_type']==='promoted'=>'Promoted FYP2',$s['stage_status']==='failed'&&str_ends_with($s['programme_type'],'fyp1')=>'Retake FYP1',$s['stage_status']==='failed'&&str_ends_with($s['programme_type'],'fyp2')=>'Retake FYP2',$s['enrolment_type']==='retake'&&str_ends_with($s['programme_type'],'fyp1')=>'Retake FYP1',$s['enrolment_type']==='retake'&&str_ends_with($s['programme_type'],'fyp2')=>'Retake FYP2',$s['enrolment_type']==='new'&&str_ends_with($s['programme_type'],'fyp1')=>'Newly Registered FYP1',default=>ucfirst($s['stage_status'])}; ?><tr><td><?= e($s['matric_number']) ?></td><td><strong><?= e($s['full_name']) ?></strong><div class="small text-muted"><?= e($s['email']) ?></div></td><td><span class="badge-fy badge-info"><?= e(ucfirst($s['level'])) ?></span><div class="small text-muted"><?= e(programmeTypeLabel($s['programme_type'])) ?></div><div class="small fw-semibold mt-1"><?= e($progressionLabel) ?></div><div class="small text-muted">Attempt <?= (int)$s['attempt_number'] ?></div></td><td class="small"><?= e($s['programme']) ?></td><td><span class="badge-fy badge-<?= statusBadgeColor($s['status']) ?>"><?= !$s['email_verified']?'Awaiting Approval':e(ucfirst($s['status'])) ?></span></td><td><div class="d-flex gap-1 flex-wrap"><form method="post"><?= csrfField() ?><input type="hidden" name="action" value="toggle_status"><input type="hidden" name="user_id" value="<?= (int)$s['user_id'] ?>"><button class="btn-fy-outline btn-sm"><?= $s['status']==='active'?'Deactivate':(!$s['email_verified']?'Approve & Activate':'Activate') ?></button></form><form method="post" onsubmit="return confirm('Permanently delete this student account? This cannot be undone.')"><?= csrfField() ?><input type="hidden" name="action" value="delete_user"><input type="hidden" name="user_id" value="<?= (int)$s['user_id'] ?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></div></td></tr><?php endforeach; ?>
<?php if(!$filteredStudents): ?><tr><td colspan="6" class="text-center text-muted py-4">No students found.</td></tr><?php endif; ?></tbody></table>
<?php else: ?>
<table class="table-fy"><thead><tr><th>Lecturer</th><th>Department</th><th>Roles (ordered)</th><th>Status</th><th>Action</th></tr></thead><tbody>
<?php foreach($lecturers as $l): ?><tr><td><strong><?= e(drName($l['full_name'])) ?></strong><div class="small text-muted"><?= e($l['email']) ?></div></td><td class="small">Department of Computing</td><td><?php $pairs=array_filter(explode(';;',(string)$l['role_pairs']));if(!$pairs): ?><span class="text-muted small">No role</span><?php else: ?><div class="d-flex flex-column gap-1"><?php foreach($pairs as $pair): [$rt,$pt]=array_pad(explode('|',$pair,2),2,''); ?><span class="small"><strong><?= e(roleLabel($rt)) ?></strong> — <?= e(programmeTypeLabel($pt)) ?></span><?php endforeach; ?></div><?php endif; ?></td><td><span class="badge-fy badge-<?= statusBadgeColor($l['status']) ?>"><?= e(ucfirst($l['status'])) ?></span></td><td><div class="d-flex gap-1 flex-wrap"><form method="post"><?= csrfField() ?><input type="hidden" name="action" value="toggle_status"><input type="hidden" name="user_id" value="<?= (int)$l['user_id'] ?>"><button class="btn-fy-outline btn-sm"><?= $l['status']==='active'?'Deactivate':'Activate' ?></button></form><form method="post" onsubmit="return confirm('Permanently delete this lecturer? Assignments will be cleared and this cannot be undone.')"><?= csrfField() ?><input type="hidden" name="action" value="delete_user"><input type="hidden" name="user_id" value="<?= (int)$l['user_id'] ?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></div></td></tr><?php endforeach; ?>
<?php if(!$lecturers): ?><tr><td colspan="5" class="text-center text-muted py-4">No lecturers found.</td></tr><?php endif; ?></tbody></table>
<?php endif; ?></div></div>

