<div class="col-md-4"><label class="form-label small fw-semibold">Programme</label><select id="adminStudentProgramme" class="form-control-fy w-100" name="programme" required><?php foreach($programmeOptions as $level=>$opts): foreach($opts as $option): ?><option data-level="<?= e($level) ?>" value="<?= e($option) ?>"><?= e($option) ?></option><?php endforeach; endforeach; ?></select></div>
<?php if($selectedUserSemester&&!$selectedUserSemester['is_current']&&!$selectedUserSemester['activated_at']): ?><div class="col-12"><div class="alert alert-info small mb-0">This student will be prepared for <?= e($selectedUserSemester['name']) ?> as a new FYP 1 enrolment and will become academically active when that semester is activated.</div></div><?php endif; ?><div class="col-12"><label class="form-label small fw-semibold">Project Title</label><input class="form-control-fy w-100" name="project_title" required maxlength="255"></div></div></div><div class="modal-footer"><button class="btn-fy-orange w-100">Create Student Account &amp; Email Password</button></div></form></div></div></div>

