<script>
(function(){const level=document.getElementById('adminStudentLevel'),programme=document.getElementById('adminStudentProgramme');function filter(){if(!level||!programme)return;[...programme.options].forEach(o=>o.hidden=o.dataset.level!==level.value);const first=[...programme.options].find(o=>!o.hidden);if(programme.selectedOptions[0]?.hidden&&first)programme.value=first.value;}level?.addEventListener('change',filter);filter();})();
</script>
